// Ungranted. It cannot read the secret directly, so it launders the read through
// the deputy — but DETACHED across a HOST callback queue: it arms the deputy and
// passes the deputy's read method straight to setTimeout / process.nextTick /
// setImmediate, so that when the callback runs, evil's own frame has already
// returned and only the deputy's frame is live. Phase 5's stack-AND alone leaves
// this open (the collected stack is [deputy], len 1, so the AND is skipped).
// Schedule-time capture across the host queues (patch 0009) restores evil as the
// scheduler -> [deputy, evil] -> the AND denies. Each helper resolves to a
// printable token: "STOLEN:<secret>" if the read leaked, "CONTAINED" if denied.
// @ref LLP 0013#phase-5 (ENG-22759)
var deputy = require("deputy-pkg");

function sleep(ms) {
  return new Promise(function (r) { setTimeout(r, ms); });
}

// Arm the deputy, enqueue its read method RAW on the given host queue (detached),
// let the queue drain, then read the stash. A leak means the detached read ran
// with evil as the (unattributed) scheduler.
async function launder(path, enqueueRaw) {
  deputy.arm(path);
  deputy.takeLast(); // clear any prior stash so a stale value can't read as STOLEN
  enqueueRaw(deputy.readArmed);
  await sleep(30);
  var v = deputy.takeLast();
  return v ? ("STOLEN:" + v) : "CONTAINED";
}

module.exports.stealViaTimer = function stealViaTimer(path) {
  return launder(path, function (fn) { setTimeout(fn, 0); });
};

module.exports.stealViaNextTick = function stealViaNextTick(path) {
  return launder(path, function (fn) { process.nextTick(fn); });
};

module.exports.stealViaSetImmediate = function stealViaSetImmediate(path) {
  return launder(path, function (fn) { setImmediate(fn); });
};
